func (h *repositoryHandler) GetRepositoryReport(w http.ResponseWriter, r *http.Request) {
	monitoring.ScanAmount.Inc()
	startTime := time.Now()
	defer func() {
		monitoring.ResponseTime.Observe(float64(time.Since(startTime).Milliseconds()))
	}()
	// get the repository URL from path params
	repositoryURL := r.PathValue("repositoryURL")
	if repositoryURL == "" {
		slog.Error("repository URL is missing", "repositoryURL", repositoryURL) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		http.Error(w, "repository URL is missing", http.StatusBadRequest)
		return
	}

	// URL decode the repository URL
	decodedRepositoryURL, err := url.PathUnescape(repositoryURL)
	if err != nil {
		slog.Error("failed to decode repository URL", "err", err, "repositoryURL", repositoryURL) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		http.Error(w, "failed to decode repository URL", http.StatusBadRequest)
		return
	}

	// check if the repository URL is valid
	if _, err := url.ParseRequestURI(decodedRepositoryURL); err != nil {
		slog.Error("invalid repository URL", "err", err, "repositoryURL", decodedRepositoryURL) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		http.Error(w, "invalid repository URL", http.StatusBadRequest)
		return
	}

	ctxWithoutCancel := context.WithoutCancel(r.Context())

	sarif, err, shared := h.Do(repositoryURL, func() (any, error) {
		// get the project as sanity check - if this fails, we can return a 404
		client, err := config.GetMatchingGitClient(decodedRepositoryURL)
		if err != nil {
			return nil, httpErr(http.StatusInternalServerError, pkgerrors.Wrapf(err, "failed to get matching git client for URL: %s", decodedRepositoryURL))
		}

		_, err = client.GetProject(ctxWithoutCancel, decodedRepositoryURL, common.GetProjectOptions{License: false})
		if err != nil {
			return nil, httpErr(http.StatusNotFound, pkgerrors.Wrapf(err, "failed to get project for URL: %s", decodedRepositoryURL))
		}

		slog.Info("running checks against repository", "repository", decodedRepositoryURL) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622

		enabledObservers := config.GetNeededObservers()
		// run the checks
		observations, err := runChecks(ctxWithoutCancel, enabledObservers, decodedRepositoryURL)

		if err != nil {
			return nil, pkgerrors.Wrapf(err, "failed to run checks for URL: %s", decodedRepositoryURL)
		}

		badgesResult := badges.Eval(decodedRepositoryURL, observations, config.RuntimeConfig.Badges)

		// transform the checkResults
		sarif, err := transformer.ConvertBadgeResultsToSarif(decodedRepositoryURL, client.IsRepoMirrored(ctxWithoutCancel, decodedRepositoryURL), badgesResult)
		if err != nil {
			return nil, pkgerrors.Wrapf(err, "failed to transform results to SARIF for URL: %s", decodedRepositoryURL)
		}

		return sarif, nil
	})

	if err != nil {
		code := http.StatusInternalServerError
		if he, ok := errors.AsType[*httpStatusError](err); ok {
			code = he.code
		}
		if code == http.StatusNotFound {
			slog.Warn("repository not found", "repositoryURL", decodedRepositoryURL, "err", err) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		} else {
			slog.Error("failed to execute repository checks", "repositoryURL", decodedRepositoryURL, "err", err) // #nosec G706 // False Positive: https://github.com/securego/gosec/issues/1622
		}
		http.Error(w, "failed to execute repository checks", code)
		return
	}
	slog.Info("successfully executed repository checks", "repositoryURL", decodedRepositoryURL, "shared", shared) // #nosec G706 // False Positive

	// write the response
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_, err = w.Write(sarif.([]byte)) // #nosec G705 // False Positive: We are providing a JSON response, not an HTML response, so this is not vulnerable to XSS
	if err != nil {
		slog.Error("failed to write response", "err", err)
		http.Error(w, "failed to write response", http.StatusInternalServerError)
		return
	}
}
